import{_ as d,o as t,c as o,a0 as r}from"./chunks/framework.CR-yHhk1.js";const l=JSON.parse('{"title":"Environment","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md"}'),c={name:"reference/environment.md"};function a(i,e,s,n,h,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="environment" tabindex="-1">Environment <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;Environment&quot;">​</a></h1><p>There is no hand-rolled <code>sepia</code> binary: the command ships as the tamias pack in <code>libraries/sepia/</code> — a generated <code>bins[]</code> shim that runs <code>tamias-driver-sepia cli</code> → <code>sepia_cli::run_from</code> in-process (T-012). Every verb behaves identically through the shim; <code>sepia --help</code> (and the <a href="/sepia/reference/cli.html">CLI reference</a>) is authoritative — this page is the env map.</p><p>Read by <code>sepia serve</code> and the store verbs; driver discovery and store paths apply to the <code>serve</code> child, so set them in its environment.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>SEPIA_HOME</code></td><td>platform data dir</td><td>sepia&#39;s own state dir (<code>node.json</code>, meta overlay)</td></tr><tr><td><code>SEPIA_NODE</code></td><td>—</td><td>node identity written into <code>node.json</code></td></tr><tr><td><code>SEPIA_NAME</code></td><td>—</td><td>display name for this node</td></tr><tr><td><code>SEPIA_DRIVER_DIR</code></td><td>—</td><td>extra driver discovery dir (first in order)</td></tr><tr><td><code>SEPIA_CLAUDE_DIR</code></td><td><code>~/.claude</code></td><td>Claude Code config/session dir</td></tr><tr><td><code>SEPIA_CURSOR_DIR</code></td><td><code>~/.cursor</code></td><td>Cursor dir</td></tr><tr><td><code>SEPIA_CLINE_DIR</code></td><td>cwd</td><td>Cline dir</td></tr><tr><td><code>SEPIA_DEVIN_DIR</code></td><td>platform data dir</td><td>Devin CLI dir</td></tr><tr><td><code>SEPIA_DEVIN_DB</code></td><td><code>&lt;devin dir&gt;/sessions.db</code></td><td>Devin sessions SQLite path</td></tr><tr><td><code>SEPIA_DEVIN_READONLY</code></td><td>off</td><td>open the Devin DB read-only</td></tr><tr><td><code>SEPIA_AGENT_&lt;ID&gt;_COMMAND</code></td><td>—</td><td>override the agent CLI command per driver (e.g. <code>SEPIA_AGENT_CLAUDE_COMMAND</code>)</td></tr><tr><td><code>SEPIA_EVENT_BUFFER</code></td><td>—</td><td>session-event buffer size</td></tr><tr><td><code>SEPIA_IDLE_TTL_MS</code></td><td>—</td><td>idle session TTL</td></tr><tr><td><code>SEPIA_SWEEP_MS</code></td><td>—</td><td>sweeper interval</td></tr><tr><td><code>SEPIA_LOCK_TTL_MS</code></td><td>—</td><td>session lock TTL</td></tr><tr><td><code>SEPIA_HISTORY_LIMIT</code></td><td>—</td><td>prompt-history cap</td></tr><tr><td><code>SEPIA_OTEL_ENDPOINT</code></td><td>—</td><td>OTLP endpoint (opt-in telemetry)</td></tr><tr><td><code>SEPIA_OTEL_SERVICE_NAME</code></td><td>—</td><td>OTEL service name</td></tr><tr><td><code>SEPIA_INHERIT_ENV</code></td><td>—</td><td>env vars passed through to agent subprocesses</td></tr><tr><td><code>SEPIA_DEBUG</code></td><td>—</td><td>debug logging</td></tr><tr><td><code>SEPIA_BIN</code></td><td>—</td><td>path to a <code>sepia</code>-shaped executable the view driver spawns for <code>serve</code> (the tamias shim, a legacy binary, or a test fake)</td></tr></tbody></table><h2 id="the-driver-ops-surface" tabindex="-1">The driver ops surface <a class="header-anchor" href="#the-driver-ops-surface" aria-label="Permalink to &quot;The driver ops surface&quot;">​</a></h2><p><code>tamias-driver-sepia</code> doubles as the generated-surface driver (P-021). <code>ops</code> answers an ops manifest derived from the clap tree: every bounded verb is a <code>cli.&lt;verb&gt;</code> wire query — <code>driver</code>, <code>list</code>, <code>export</code>, <code>import</code>, <code>install</code>, <code>delete</code>, <code>config</code>, <code>version</code> and friends, 18 ops total — dispatched through <code>sepia_cli::run_from</code> in a captured child. <code>run &lt;argv&gt;</code> is the raw passthrough; <code>cli &lt;argv&gt;</code> is the <code>bins[]</code> shim verb the <code>sepia</code> command itself execs (inherited stdio, so <code>sepia serve</code> streams end-to-end). <code>serve</code> is listed under <code>surfaces</code>, never an op — it never returns. A feature-gated <code>mcp</code> mode renders the same manifest as MCP tools via pavo-driver-kit.</p>',6)])])}const v=d(c,[["render",a]]);export{l as __pageData,v as default};
